def give_existing_players_an_avatar(apps, schema_editor):
    """The same rule new accounts get, so people who signed up earlier don't all look alike."""
    Player = apps.get_model("game", "Player")
    for player in Player.objects.select_related("user"):
        player.avatar_index = int(hashlib.sha256(player.user.username.encode()).hexdigest(), 16) % 16
        player.save(update_fields=["avatar_index"])


